93|export function getStandardChromeUserAgent(chromiumVersion: string = process.versions.chrome): string {
94|  if (!/^\d+(?:\.\d+){1,3}$/.test(chromiumVersion)) {
95|    throw new Error('Electron did not provide a valid embedded Chromium version.')
96|  }
97|
98|  const plat = process.platform
99|  const suffix = `AppleWebKit/537.36 (KHTML, like Gecko) Chrome/${chromiumVersion} Safari/537.36`
100|
101|  if (plat === 'darwin') {
102|    return `Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) ${suffix}`
103|  }
104|
105|  if (plat === 'linux') {
106|    return `Mozilla/5.0 (X11; Linux x86_64) ${suffix}`
107|  }
108|
109|  return `Mozilla/5.0 (Windows NT 10.0; Win64; x64) ${suffix}`
110|}
