209|function workstationControllerFault(
210|  error_code: WorkstationControllerError['error_code'],
211|  message: string,
212|  options: Partial<Omit<WorkstationControllerError, 'error_code' | 'message'>> = {}
213|): WorkstationControllerFault {
214|  const defaults: Record<
215|    WorkstationControllerError['error_code'],
216|    Omit<WorkstationControllerError, 'error_code' | 'message'>
217|  > = {
218|    STALE_REF: {
219|      retryable: true,
220|      retry_after_ms: 0,
221|      state_changed: true,
222|      recommended_action: 'RESNAPSHOT',
223|      details: {}
224|    },
225|    NO_BOUND_TAB: {
226|      retryable: true,
227|      retry_after_ms: 0,
228|      state_changed: true,
229|      recommended_action: 'BIND_OR_NAVIGATE',
230|      details: {}
231|    },
232|    AUTH_REQUIRED: {
233|      retryable: false,
234|      retry_after_ms: 0,
235|      state_changed: false,
236|      recommended_action: 'REAUTHENTICATE_CONTROLLER',
237|      details: {}
238|    },
239|    USER_CONTROL_ACTIVE: {
240|      retryable: true,
241|      retry_after_ms: 0,
242|      state_changed: true,
243|      recommended_action: 'WAIT_FOR_RELEASE',
244|      details: {}
245|    },
246|    CAPABILITY_MISSING: {
247|      retryable: false,
248|      retry_after_ms: 0,
249|      state_changed: false,
250|      recommended_action: 'ESCALATE',
251|      details: {}
252|    },
253|    TIMEOUT: {
254|      retryable: true,
255|      retry_after_ms: 0,
256|      state_changed: false,
257|      recommended_action: 'RETRY_WITH_BACKOFF',
258|      details: {}
259|    },
260|    TIMEOUT_UNCERTAIN: {
261|      retryable: false,
262|      retry_after_ms: 0,
263|      state_changed: true,
264|      recommended_action: 'RECONCILE_EFFECT',
265|      details: {}
266|    },
267|    INVALID_ARGUMENT: {
268|      retryable: false,
269|      retry_after_ms: 0,
270|      state_changed: false,
271|      recommended_action: 'CORRECT_REQUEST',
272|      details: {}
273|    },
274|    FORBIDDEN_DESTINATION: {
275|      retryable: false,
276|      retry_after_ms: 0,
277|      state_changed: false,
278|      recommended_action: 'REVISE_DESTINATION',
279|      details: {}
280|    },
281|    NETWORK_ERROR: {
282|      retryable: true,
283|      retry_after_ms: 500,
284|      state_changed: false,
285|      recommended_action: 'RETRY_READ',
286|      details: {}
287|    },
288|    PAYLOAD_TOO_LARGE: {
289|      retryable: false,
290|      retry_after_ms: 0,
291|      state_changed: false,
292|      recommended_action: 'NARROW_READBACK',
293|      details: {}
294|    },
295|    CONTROLLER_DOWN: {
296|      retryable: true,
297|      retry_after_ms: 0,
298|      state_changed: true,
299|      recommended_action: 'RECONCILE_CONTROLLER',
300|      details: {}
301|    }
302|  }
303|
304|  return new WorkstationControllerFault({ error_code, message, ...defaults[error_code], ...options })
