307|/** Map legacy controller failures without granting semantics from incidental prose. */
308|export function normalizeWorkstationControllerError(error: unknown, resourceRef?: string): WorkstationControllerError {
309|  if (error instanceof WorkstationControllerFault) {
310|    return { ...error.structured, resource_ref: error.structured.resource_ref ?? resourceRef }
311|  }
312|
313|  const message = error instanceof Error ? error.message : String(error)
314|  const token = message.trim().toLowerCase()
315|  const base = { message, retry_after_ms: 0, resource_ref: resourceRef, details: { compatibility_path: true } }
316|
317|  if (token === 'human control active' || token.startsWith('human control active:')) {
318|    return {
319|      ...base,
320|      error_code: 'USER_CONTROL_ACTIVE',
321|      retryable: true,
322|      state_changed: true,
323|      recommended_action: 'WAIT_FOR_RELEASE'
324|    }
325|  }
326|
327|  if (token.startsWith('no_bound_browser_tab:') || token === 'no active tab') {
328|    return {
329|      ...base,
330|      error_code: 'NO_BOUND_TAB',
331|      retryable: true,
332|      state_changed: true,
333|      recommended_action: 'BIND_OR_NAVIGATE'
334|    }
335|  }
336|
337|  if (token === 'ref_required' || token === 'element_unavailable' || token === 'browser_tab_destroyed') {
338|    return { ...base, error_code: 'STALE_REF', retryable: true, state_changed: true, recommended_action: 'RESNAPSHOT' }
339|  }
340|
341|  if (token === 'timeout' || token === 'timed out') {
342|    return {
343|      ...base,
344|      error_code: 'TIMEOUT',
345|      retryable: true,
346|      state_changed: false,
347|      recommended_action: 'RETRY_WITH_BACKOFF'
348|    }
349|  }
350|
351|  if (token === 'controller_unavailable' || token === 'controller_down') {
352|    return {
353|      ...base,
354|      error_code: 'CONTROLLER_DOWN',
355|      retryable: true,
356|      state_changed: true,
357|      recommended_action: 'RECONCILE_CONTROLLER'
358|    }
359|  }
360|
361|  if (token === 'unsupported_action' || token === 'invalid_extension_options_request') {
362|    return {
363|      ...base,
364|      error_code: 'INVALID_ARGUMENT',
365|      retryable: false,
366|      state_changed: false,
367|      recommended_action: 'CORRECT_REQUEST'
368|    }
369|  }
370|
371|  return {
372|    ...base,
373|    error_code: 'CAPABILITY_MISSING',
374|    retryable: false,
375|    state_changed: false,
376|    recommended_action: 'ESCALATE'
377|  }
