519|export function normalizeWorkstationBrowserTarget(value: string): string {
520|  const raw = String(value ?? '').trim()
521|
522|  if (!raw) {
523|    return 'about:blank'
524|  }
525|
526|  if (raw === 'about:blank') {
527|    return raw
528|  }
529|
530|  try {
531|    const parsed = new URL(raw)
532|
533|    if (parsed.protocol === 'http:' || parsed.protocol === 'https:') {
534|      return parsed.toString()
535|    }
536|  } catch {
537|    // Fall through to hostname/search heuristics.
538|  }
539|
540|  const localish = /^(localhost|127\.0\.0\.1|\[::1\])(?::\d+)?(?:\/.*)?$/i.test(raw)
541|
542|  if (localish) {
543|    return `http://${raw}`
544|  }
545|
546|  const hostish = /^[a-z0-9.-]+\.[a-z]{2,}(?::\d+)?(?:\/.*)?$/i.test(raw)
547|
548|  if (hostish) {
549|    return `https://${raw}`
550|  }
551|
552|  return `https://duckduckgo.com/?q=${encodeURIComponent(raw)}`
553|}
