555|function blockedSensitiveNetworkUrl(url: string): boolean {
556|  try {
557|    const parsed = new URL(url)
558|    const host = parsed.hostname.replace(/^\[|\]$/g, '').toLowerCase()
559|
560|    if (host === 'metadata.google.internal' || host === 'metadata.goog' || host === '100.100.100.200') {
561|      return true
562|    }
563|
564|    if (host.startsWith('169.254.')) {
565|      return true
566|    }
567|
568|    if (host === 'fd00:ec2::254') {
569|      return true
570|    }
571|
572|    if (host.startsWith('::ffff:169.254.')) {
573|      return true
574|    }
575|
576|    if (host === '::ffff:100.100.100.200') {
577|      return true
578|    }
579|
580|    return false
581|  } catch {
582|    return false
583|  }
584|}
