608|function readBody(req: IncomingMessage): Promise<string> {
609|  return new Promise((resolve, reject) => {
610|    let body = ''
611|    let bytes = 0
612|    req.setEncoding('utf-8')
613|    req.on('data', (chunk: string) => {
614|      bytes += Buffer.byteLength(chunk)
615|
616|      if (bytes > MAX_CONTROL_BODY_BYTES) {
617|        reject(new Error('request body too large'))
618|        req.destroy()
619|
620|        return
621|      }
622|
623|      body += chunk
624|    })
625|    req.on('end', () => resolve(body))
626|    req.on('error', reject)
627|  })
628|}
