634|function controllerSessionIdentity(value: unknown): string | null {
635|  if (value === undefined || value === null) {
636|    return null
637|  }
638|
639|  if (typeof value !== 'string') {
640|    throw new Error('invalid session identity')
641|  }
642|
643|  const normalized = value.trim()
644|
645|  // eslint-disable-next-line no-control-regex
646|  if (!normalized || normalized.length > MAX_CONTROLLER_SESSION_ID_CHARS || /[\u0000-\u001f\u007f]/.test(value)) {
647|    throw new Error('invalid session identity')
648|  }
649|
650|  return normalized
651|}
