672|function atomicWritePrivateJson(filePath: string, value: unknown): void {
673|  fs.mkdirSync(path.dirname(filePath), { recursive: true })
674|  const temp = `${filePath}.${process.pid}.tmp`
675|  fs.writeFileSync(temp, JSON.stringify(value, null, 2), { encoding: 'utf-8', mode: 0o600 })
676|
677|  try {
678|    fs.renameSync(temp, filePath)
679|  } catch (err: any) {
680|    if (err && (err.code === 'EPERM' || err.code === 'EBUSY')) {
681|      fs.copyFileSync(temp, filePath)
682|      fs.rmSync(temp, { force: true })
683|    } else {
684|      throw err
685|    }
686|  }
687|
688|  try {
689|    fs.chmodSync(filePath, 0o600)
690|  } catch {
691|    // Best effort on Windows / filesystems without POSIX permissions.
692|  }
693|}
