203|export function normalizeBrowserTaskSnapshot(value: unknown): BrowserTaskSnapshot | null {
204|  if (!value || typeof value !== 'object') {
205|    return null
206|  }
207|
208|  const snapshot = value as { version?: unknown; browserTaskCounter?: unknown; tasks?: unknown }
209|
210|  if (snapshot.version !== BROWSER_TASK_STATE_VERSION) {
211|    return null
212|  }
213|
214|  if (!Number.isInteger(snapshot.browserTaskCounter) || Number(snapshot.browserTaskCounter) < 0) {
215|    return null
216|  }
217|
218|  if (!Array.isArray(snapshot.tasks)) {
219|    return null
220|  }
221|
222|  // One logical task may appear only once. If a crash left duplicate metadata,
223|  // keep the most recently updated valid record and discard the stale duplicate.
224|  const deduped = new Map<string, BrowserTask>()
225|
226|  for (const raw of snapshot.tasks) {
227|    const parsed = parsePersistedTask(raw)
228|
229|    if (!parsed) {
230|      continue
231|    }
232|
233|    const current = deduped.get(parsed.taskId)
234|
235|    if (!current || parsed.updatedAt >= current.updatedAt) {
236|      deduped.set(parsed.taskId, parsed)
237|    }
238|  }
239|
240|  return {
241|    version: BROWSER_TASK_STATE_VERSION,
242|    browserTaskCounter: Number(snapshot.browserTaskCounter),
243|    tasks: [...deduped.values()]
244|  }
