```ts
import { useEffect } from 'react'

import type { WorkstationBrowserBridge } from './types'

export const NATIVE_VIEW_OCCLUDER_SELECTOR = '[data-native-view-occluder="true"]'

export function isNativeViewOccluded(root: ParentNode = document): boolean {
  return Boolean(root.querySelector(NATIVE_VIEW_OCCLUDER_SELECTOR))
}

/** Extra reason a host keeps its native view off screen, independent of overlays:
 *  a keep-alive pane that is not the active tab, or a host whose layout box
 *  collapsed to nothing. Both leave the pane mounted with a rect that no longer
 *  matches what the user sees, and the view is an OS-level child of the window
 *  content view — it paints above the DOM and swallows the clicks of whatever
 *  the user is actually looking at. */
export type NativeViewGate = {
  enabled?: boolean
}

/**
 * The single authority over whether a host's native browser view is on screen.
 * `enabled: false` parks the view without tearing down its session; an overlay
 * carrying `data-native-view-occluder="true"` parks it too, because the view
 * would otherwise sit above that overlay and eat its clicks.
 */
export function useNativeViewOcclusion(
  bridge: WorkstationBrowserBridge | null | undefined,
  host: 'hub' | 'chat',
  gate?: NativeViewGate
): void {
  const enabled = gate?.enabled ?? true

  useEffect(() => {
    if (!bridge?.setVisible) {
      return
    }

    let shown: boolean | null = null
    let frame = 0

    const apply = () => {
      const next = enabled && !isNativeViewOccluded(document)

      if (next === shown) {
        return
      }

      shown = next
      void bridge.setVisible(next, host)
    }

    // Coalesce to one frame: the observer sees every streaming-chat mutation and
    // a whole-document query per mutation is what made this hook hot.
    const schedule = () => {
      if (frame) {
        return
      }

      frame = requestAnimationFrame(() => {
        frame = 0
        apply()
      })
    }

    // An overlay can already be open when the pane mounts (e.g. switching tabs
    // while a dialog is up), so seed the state instead of waiting for a mutation.
    apply()

    const observer = new MutationObserver(schedule)
    observer.observe(document.body, { childList: true, subtree: true })

    return () => {
      observer.disconnect()

      if (frame) {
        cancelAnimationFrame(frame)
      }

      // Hand the viewport back on screen for whoever owns it next.
      if (shown === false) {
        void bridge.setVisible(true, host)
      }
    }
  }, [bridge, host, enabled])
}
```

Wait — careful with the `enabled` dep: when `enabled` flips, the effect re-runs (cleanup then setup). The cleanup with `shown === false` calls `setVisible(true, host)` — which would briefly re-show the view then apply() hides it again. Both are async IPC calls → could flicker. Better: make the cleanup NOT restore when the effect is just re-running due to `enabled`. Hmm, the original code's cleanup purpose: on unmount while hidden, restore so the next owner isn't left hidden. But `attach`/`transferViewport` set visibility themselves... Actually a simpler correct approach: keep the restore but only on real unmount — I can distinguish using a ref, or split into two effects: one that owns the observer + occluder state, and one that applies visibility from (occluded, enabled).

