  /**
   * Extra reason to park the view, independent of overlays: a keep-alive pane
   * that is not the active tab, or a host whose layout box collapsed to
   * nothing. Both keep the pane mounted with a rect that no longer matches what
   * the user sees, and the view is an OS-level child of the window content view
   * — it paints above the DOM and swallows the clicks of whatever is actually
   * on screen there.
   */
  enabled?: boolean
}

export interface NativeViewOcclusionHandle {
  /** True while a `data-native-view-occluder` surface is mounted. */
  occluded: boolean
  /** Re-assert the composed visibility now (attach() forces the view back on). */
  assertVisible: () => void
}

/**
 * The single authority over whether a host's native browser view is on screen.
 * Parking keeps the page and its session alive — it only removes the child view.
 */
